INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht man unter Ausfallsicherung im IT-Bereich?', 2, '[{"text": "Maßnahmen gegen Systemausfälle", "correct": true, "because": "Sichert Verfügbarkeit"}, {"text": "Softwareverschlüsselung", "correct": false, "because": "Anderer Fokus"}, {"text": "Hardwarewartung", "correct": false, "because": "Teil, aber nicht alles"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Ausfallsicherung als Fachinformatiker?', 3, '[{"text": "Hohe Verfügbarkeit gewährleisten", "correct": true, "because": "Minimiert Downtime"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Design optimieren", "correct": false, "because": "Kein primäres Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken gehören zur Ausfallsicherung?', 5, '[{"text": "Redundanz", "correct": true, "because": "Doppelte Systeme"}, {"text": "Failover", "correct": true, "because": "Automatische Umschaltung"}, {"text": "Softwareentwicklung", "correct": false, "because": "Kein direkter Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Redundanz erhöht die Ausfallsicherung. b) Sie macht Backups überflüssig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Backups ergänzen Redundanz"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung von Ausfallsicherung?', 4, '[{"text": "Verfügbarkeitsanforderungen", "correct": false, "because": "Entscheidend für Planung"}, {"text": "Redundanzmechanismen", "correct": false, "because": "Kern der Sicherung"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein RAID-System zur Ausfallsicherung gehört?', 2, '[{"text": "Ja", "correct": true, "because": "Schützt vor Festplattenausfall"}, {"text": "Nein", "correct": false, "because": "Teil der Strategie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche RAID-Stufe bietet Ausfallsicherung ohne Datenverlust?', 3, '[{"text": "RAID 1", "correct": true, "because": "Spiegelung der Daten"}, {"text": "RAID 0", "correct": false, "because": "Keine Redundanz"}, {"text": "RAID 5 ohne Parität", "correct": false, "because": "Parität erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Ausfallsicherung in einem Serverraum?', 5, '[{"text": "USV (Unterbrechungsfreie Stromversorgung)", "correct": true, "because": "Stromausfall absichern"}, {"text": "Redundante Netzwerkverbindungen", "correct": true, "because": "Netzwerkausfall verhindern"}, {"text": "Bürogestaltung", "correct": false, "because": "Kein technischer Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Failover-System ist Teil der Ausfallsicherung. b) Es macht Hardwarewartung überflüssig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wartung bleibt nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Ausfallsicherung unwichtig?', 4, '[{"text": "Redundanz", "correct": false, "because": "Kernprinzip"}, {"text": "Backup-Strategie", "correct": false, "because": "Wichtiger Bestandteil"}, {"text": "Farbe der Server", "correct": true, "because": "Kein technischer Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss Ausfallsicherung teuer sein?', 2, '[{"text": "Nein", "correct": true, "because": "Kosten variieren"}, {"text": "Ja", "correct": false, "because": "Abhängig von Umfang"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Ausfallsicherung für einen Fachinformatiker?', 4, '[{"text": "Geringere Downtime", "correct": true, "because": "Systeme bleiben verfügbar"}, {"text": "Datensicherheit", "correct": true, "because": "Schutz vor Verlust"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Ausfallsicherung nur Hardware betrifft. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Softwarelösungen"}, {"text": "Ja", "correct": false, "because": "Umfassender Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Ausfallsicherung?', 3, '[{"text": "Verfügbarkeit", "correct": true, "because": "Hauptziel"}, {"text": "Kostenreduktion", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Backup ist Teil der Ausfallsicherung. b) Es ersetzt Redundanz.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Redundanz ergänzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine unzureichende Ausfallsicherung?', 5, '[{"text": "Datenverlust", "correct": true, "because": "Keine Absicherung"}, {"text": "Systemausfall", "correct": true, "because": "Downtime möglich"}, {"text": "Hohe Flexibilität", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Ausfallsicherung unwichtig?', 3, '[{"text": "Redundanz", "correct": false, "because": "Kernprinzip"}, {"text": "Failover", "correct": false, "because": "Wichtige Technik"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Ausfallsicherung durch Software erreicht werden?', 3, '[{"text": "Ja", "correct": true, "because": "z.B. Failover-Software"}, {"text": "Nein", "correct": false, "because": "Nicht nur Hardware"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Load Balancer zur Ausfallsicherung beiträgt?', 2, '[{"text": "Ja", "correct": true, "because": "Verteilt Last, erhöht Verfügbarkeit"}, {"text": "Nein", "correct": false, "because": "Teil der Strategie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wähle ich für Ausfallsicherung bei Servern?', 4, '[{"text": "Cluster", "correct": true, "because": "Mehrere Server als Einheit"}, {"text": "Einzelserver", "correct": false, "because": "Keine Redundanz"}, {"text": "Bürodesign", "correct": false, "because": "Kein technischer Bezug"}]');
